export function validWorldAsset(kind,d){
 if(!worldAssetTypes[kind]||d?.version!==1||!label(d.name))return false;
 if(kind==='mesh')return Array.isArray(d.vertices)&&d.vertices.length>=3&&d.vertices.length<=1000000&&d.vertices.every(v=>vec(v,3))&&Array.isArray(d.indices)&&d.indices.length%3===0&&d.indices.length>=3&&d.indices.length<=6000000&&d.indices.every(i=>Number.isInteger(i)&&i>=0&&i<d.vertices.length)&&Array.isArray(d.uvs)&&d.uvs.length===d.vertices.length&&d.uvs.every(v=>vec(v,2));
 if(kind==='terrain'){const n=d.resolution?.[0]*d.resolution?.[1];return vec(d.size,2,.001,1000000)&&vec(d.resolution,2,2,1025)&&d.resolution.every(Number.isInteger)&&Array.isArray(d.heights)&&d.heights.length===n&&d.heights.every(v=>finite(v,-10000,10000))&&Array.isArray(d.layers)&&d.layers.length>=1&&d.layers.length<=8&&d.layers.every(l=>label(l?.name)&&vec(l.color,3,0,1))&&Array.isArray(d.weights)&&d.weights.length===n&&d.weights.every(w=>vec(w,d.layers.length,0,1)&&Math.abs(w.reduce((a,b)=>a+b,0)-1)<1e-5);}
 if(kind==='foliage')return (d.mesh===''||path(d.mesh))&&(d.terrain===''||path(d.terrain))&&Number.isSafeInteger(d.seed)&&Array.isArray(d.instances)&&d.instances.length<=1000000&&new Set(d.instances.map(i=>i?.id)).size===d.instances.length&&d.instances.every(i=>label(i?.id)&&vec(i.position,3)&&vec(i.rotation,3,-360000,360000)&&vec(i.scale,3,.001,10000));
 return Array.isArray(d.levels)&&['distance','screen'].includes(d.mode)&&finite(d.hysteresis,0,.5)&&Number.isInteger(d.forced)&&d.forced>=-1&&d.forced<d.levels.length&&Array.isArray(d.levels)&&d.levels.length<=16&&d.levels.every((l,i)=>path(l?.asset)&&finite(l.threshold,.000001,1000000)&&(i===0||(d.mode==='distance'?l.threshold>d.levels[i-1].threshold:l.threshold<d.levels[i-1].threshold)));
}
export function meshNormals(d){const n=d.vertices.map(()=>[0,0,0]);for(let i=0;i<d.indices.length;i+=3){const ids=d.indices.slice(i,i+3),[a,b,c]=ids.map(j=>d.vertices[j]),u=b.map((v,j)=>v-a[j]),v=c.map((x,j)=>x-a[j]),q=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]];for(const id of ids)for(let j=0;j<3;j++)n[id][j]+=q[j];}return n.map(v=>{const l=Math.hypot(...v);return l?v.map(x=>x/l):[0,1,0];});}
export function editMesh(d,{operation,vertices=[],faces=[],delta=[0,0,0],distance=1}){
 if(!validWorldAsset('mesh',d)||!Array.isArray(vertices)||!vertices.every(i=>Number.isInteger(i)&&i>=0&&i<d.vertices.length)||!Array.isArray(faces)||!faces.every(i=>Number.isInteger(i)&&i>=0&&i<d.indices.length/3)||!vec(delta,3)||!finite(distance))throw Error('메시 선택·연산 값을 확인하세요.');
 const n=structuredClone(d),selected=new Set(faces);
 if(operation==='move')for(const id of new Set(vertices))n.vertices[id]=n.vertices[id].map((v,i)=>v+delta[i]);
 else if(operation==='deleteFaces')n.indices=d.indices.filter((_,i)=>!selected.has(Math.floor(i/3)));
 else if(operation==='flip')for(const id of selected)[n.indices[id*3+1],n.indices[id*3+2]]=[n.indices[id*3+2],n.indices[id*3+1]];
 else if(operation==='subdivide'){const edges=new Map(),mid=(a,b)=>{const key=[a,b].sort((x,y)=>x-y).join(':');if(edges.has(key))return edges.get(key);const id=n.vertices.length;n.vertices.push(d.vertices[a].map((v,j)=>(v+d.vertices[b][j])/2));n.uvs.push(d.uvs[a].map((v,j)=>(v+d.uvs[b][j])/2));edges.set(key,id);return id;};n.indices=[];for(let i=0;i<d.indices.length/3;i++){const [a,b,c]=d.indices.slice(i*3,i*3+3);if(!selected.size||selected.has(i)){const x=mid(a,b),y=mid(b,c),z=mid(c,a);n.indices.push(a,x,z,x,b,y,z,y,c,x,y,z);}else n.indices.push(a,b,c);}}
 else if(operation==='extrude'){if(!selected.size)throw Error('면을 선택하세요.');const used=new Set([...selected].flatMap(i=>d.indices.slice(i*3,i*3+3))),normal=meshNormals({...d,indices:[...selected].flatMap(i=>d.indices.slice(i*3,i*3+3))}),remap=new Map(),edge=new Map();for(const id of used){remap.set(id,n.vertices.length);n.vertices.push(d.vertices[id].map((v,j)=>v+normal[id][j]*distance));n.uvs.push([...d.uvs[id]]);}n.indices=[];for(let i=0;i<d.indices.length/3;i++){const ids=d.indices.slice(i*3,i*3+3);n.indices.push(...(selected.has(i)?ids.map(id=>remap.get(id)):ids));if(selected.has(i))for(let j=0;j<3;j++){const a=ids[j],b=ids[(j+1)%3],key=[a,b].sort((x,y)=>x-y).join(':');if(edge.has(key))edge.delete(key);else edge.set(key,[a,b]);}}for(const [a,b] of edge.values())n.indices.push(a,b,remap.get(b),a,remap.get(b),remap.get(a));}
 else if(operation==='uvXZ')n.uvs=n.vertices.map(v=>[v[0],v[2]]);else throw Error('메시 연산 오류');
 if(!validWorldAsset('mesh',n))throw Error('메시 결과 범위를 확인하세요.');return n;
}
export function terrainMesh(d){if(!validWorldAsset('terrain',d))throw Error('지형 데이터 오류');const [w,h]=d.resolution,result={version:1,name:d.name,vertices:[],uvs:[],indices:[],colors:[]};for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=y*w+x;result.vertices.push([(x/(w-1)-.5)*d.size[0],d.heights[i],(y/(h-1)-.5)*d.size[1]]);result.uvs.push([x/(w-1),y/(h-1)]);result.colors.push([0,1,2].map(c=>d.weights[i].reduce((v,a,k)=>v+a*d.layers[k].color[c],0)));}for(let y=0;y<h-1;y++)for(let x=0;x<w-1;x++){const a=y*w+x,b=a+1,c=a+w,e=c+1;result.indices.push(a,c,b,b,c,e);}return result;}
export function terrainHeight(d,x,z){const [w,h]=d.resolution,fx=Math.max(0,Math.min(w-1,(x/d.size[0]+.5)*(w-1))),fy=Math.max(0,Math.min(h-1,(z/d.size[1]+.5)*(h-1))),a=Math.floor(fx),b=Math.floor(fy),u=fx-a,v=fy-b,s=(i,j)=>d.heights[Math.min(h-1,j)*w+Math.min(w-1,i)];return (s(a,b)*(1-u)+s(a+1,b)*u)*(1-v)+(s(a,b+1)*(1-u)+s(a+1,b+1)*u)*v;}
export function terrainBrush(d,{position=[0,0],radius=2,strength=1,mode='raise',height=0,layer=0}){
 if(!validWorldAsset('terrain',d)||!vec(position,2)||!finite(radius,.000001,1000000)||!finite(strength,0,10000)||!finite(height,-10000,10000)||!['raise','lower','flatten','smooth','paint'].includes(mode)||!Number.isInteger(layer)||layer<0||layer>=d.layers.length)throw Error('지형 브러시 오류');const n=structuredClone(d),[w,h]=d.resolution;
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){const px=(x/(w-1)-.5)*d.size[0],pz=(y/(h-1)-.5)*d.size[1],t=Math.max(0,1-Math.hypot(px-position[0],pz-position[1])/radius);if(!t)continue;const i=y*w+x,a=Math.min(1,strength*t*t*(3-2*t));if(mode==='paint'){for(let k=0;k<n.layers.length;k++)n.weights[i][k]=d.weights[i][k]*(1-a)+(k===layer?a:0);}else if(mode==='raise'||mode==='lower')n.heights[i]+=strength*t*(mode==='raise'?1:-1);else if(mode==='flatten')n.heights[i]+=(height-d.heights[i])*a;else{let sum=0,count=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(x+dx>=0&&x+dx<w&&y+dy>=0&&y+dy<h){sum+=d.heights[(y+dy)*w+x+dx];count++;}n.heights[i]+=(sum/count-d.heights[i])*a;}}
 if(!validWorldAsset('terrain',n))throw Error('지형 높이 범위를 넘었어요.');return n;
}
export function scatterFoliage(d,{center=[0,0],radius=5,count=100,minDistance=.5,scale=[.8,1.2],seed=d.seed,terrain}={}){
 if(!validWorldAsset('foliage',d)||!vec(center,2)||!finite(radius,.001,1000000)||!Number.isSafeInteger(count)||count<0||count>1000000||!finite(minDistance,.0001,100000)||!vec(scale,2,.001,10000)||scale[0]>scale[1]||!Number.isSafeInteger(seed)||terrain&&!validWorldAsset('terrain',terrain))throw Error('폴리지 산포 범위를 확인하세요.');
 const n=structuredClone(d),grid=new Map(),cell=minDistance,at=p=>[Math.floor(p[0]/cell),Math.floor(p[2]/cell)],put=p=>{const key=at(p).join(':');if(!grid.has(key))grid.set(key,[]);grid.get(key).push(p);};for(const i of d.instances)put(i.position);let state=seed>>>0;const random=()=>((state=(Math.imul(state,1664525)+1013904223)>>>0)/4294967296);let serial=0;const ids=new Set(n.instances.map(i=>i.id));for(let tries=0,added=0;tries<count*30&&added<count;tries++){const r=Math.sqrt(random())*radius,a=random()*Math.PI*2,p=[center[0]+Math.cos(a)*r,0,center[1]+Math.sin(a)*r],g=at(p);let blocked=false;for(let y=-1;y<=1;y++)for(let x=-1;x<=1;x++)for(const q of grid.get([g[0]+x,g[1]+y].join(':'))||[])if(Math.hypot(q[0]-p[0],q[2]-p[2])<minDistance)blocked=true;if(blocked)continue;if(terrain)p[1]=terrainHeight(terrain,p[0],p[2]);const size=scale[0]+(scale[1]-scale[0])*random();let id;do{id='instance_'+(seed>>>0)+'_'+serial++;}while(ids.has(id));ids.add(id);n.instances.push({id,position:p,rotation:[0,random()*360,0],scale:[size,size,size]});put(p);added++;}n.seed=state;if(!validWorldAsset('foliage',n))throw Error('폴리지 인스턴스 범위를 넘었어요.');return n;
}
export function eraseFoliage(d,position,radius){if(!validWorldAsset('foliage',d)||!vec(position,2)||!finite(radius,0))throw Error('폴리지 소거 범위를 확인하세요.');return {...structuredClone(d),instances:d.instances.filter(i=>Math.hypot(i.position[0]-position[0],i.position[2]-position[1])>radius).map(i=>structuredClone(i))};}
export function simplifyMesh(d,cellSize){if(!validWorldAsset('mesh',d)||!finite(cellSize,.000001))throw Error('LOD 단순화 범위를 확인하세요.');const buckets=new Map(),indices=[],vertices=[],uvs=[],remap=[];for(let i=0;i<d.vertices.length;i++){const v=d.vertices[i],key=v.map(x=>Math.floor(x/cellSize)).join(':')+':'+d.uvs[i].map(x=>Math.round(x*16)).join(':');let b=buckets.get(key);if(!b){b={id:vertices.length,count:0};buckets.set(key,b);vertices.push([0,0,0]);uvs.push([0,0]);}b.count++;v.forEach((x,j)=>vertices[b.id][j]+=x);d.uvs[i].forEach((x,j)=>uvs[b.id][j]+=x);remap[i]=b.id;}for(const b of buckets.values()){vertices[b.id]=vertices[b.id].map(x=>x/b.count);uvs[b.id]=uvs[b.id].map(x=>x/b.count);}const seen=new Set();for(let i=0;i<d.indices.length;i+=3){const t=d.indices.slice(i,i+3).map(j=>remap[j]),key=t.slice().sort((a,b)=>a-b).join(':');if(new Set(t).size===3&&!seen.has(key)){indices.push(...t);seen.add(key);}}const result={version:1,name:d.name,vertices,uvs,indices};if(!validWorldAsset('mesh',result))throw Error('단순화가 모든 면을 제거했어요. 셀 크기를 줄이세요.');return result;}
export function chooseLOD(d,{distance,screenHeight,previous=-1}){if(!validWorldAsset('lod',d)||!d.levels.length||!finite(distance,0)||!finite(screenHeight,0))throw Error('LOD 그룹·카메라 값을 확인하세요.');if(d.forced>=0)return d.forced;const value=d.mode==='distance'?distance:screenHeight;let index=d.levels.length-1;if(d.mode==='distance'){index=0;while(index<d.levels.length-1&&value>=d.levels[index+1].threshold)index++;}else{index=0;while(index<d.levels.length-1&&value<d.levels[index].threshold)index++;}if(previous>=0&&previous<d.levels.length&&index!==previous){const boundary=d.mode==='distance'?d.levels[Math.max(index,previous)].threshold:d.levels[Math.min(index,previous)].threshold;if(Math.abs(value-boundary)<boundary*d.hysteresis)return previous;}return index;}
export function meshColliderChunks(d,size=2048){const chunks=[];let used=new Map(),vertices=[],indices=[];const flush=()=>{if(indices.length)chunks.push({vertices,indices});used=new Map();vertices=[];indices=[];};for(let i=0;i<d.indices.length;i+=3){const tri=d.indices.slice(i,i+3);if(used.size+tri.filter(j=>!used.has(j)).length>size||indices.length>=8192*3)flush();for(const j of tri){if(!used.has(j)){used.set(j,vertices.length);vertices.push([...d.vertices[j]]);}indices.push(used.get(j));}}flush();return chunks;}
